"""Implement a Doubly Linked List — head and tail sentinels.

Two sentinels mean no insertion or deletion ever has to special-case an empty
list or an end of the list.

Time: O(index) for positional operations, O(1) for the ends   Space: O(n)
"""
from typing import List


class _Node:
    __slots__ = ("val", "prev", "next")

    def __init__(self, val=0):
        self.val = val
        self.prev = None
        self.next = None


class MyDoublyLinkedList:
    def __init__(self):
        self._head = _Node()
        self._tail = _Node()
        self._head.next = self._tail
        self._tail.prev = self._head
        self._size = 0

    def _node_at(self, index: int) -> _Node:
        if index * 2 < self._size:            # walk from whichever end is closer
            node = self._head.next
            for _ in range(index):
                node = node.next
        else:
            node = self._tail
            for _ in range(self._size - index):
                node = node.prev
        return node

    def _insert_before(self, node: _Node, val: int) -> None:
        fresh = _Node(val)
        fresh.prev = node.prev
        fresh.next = node
        node.prev.next = fresh
        node.prev = fresh
        self._size += 1

    def get(self, index: int) -> int:
        if index < 0 or index >= self._size:
            return -1
        return self._node_at(index).val

    def addAtHead(self, val: int) -> None:
        self._insert_before(self._head.next, val)

    def addAtTail(self, val: int) -> None:
        self._insert_before(self._tail, val)

    def addAtIndex(self, index: int, val: int) -> None:
        if index > self._size:
            return
        index = max(index, 0)
        self._insert_before(self._node_at(index) if index < self._size else self._tail, val)

    def deleteAtIndex(self, index: int) -> None:
        if index < 0 or index >= self._size:
            return
        node = self._node_at(index)
        node.prev.next = node.next
        node.next.prev = node.prev
        self._size -= 1

    def toArray(self) -> List[int]:
        out, node = [], self._head.next
        while node is not self._tail:
            out.append(node.val)
            node = node.next
        return out

    def toArrayReverse(self) -> List[int]:
        out, node = [], self._tail.prev
        while node is not self._head:
            out.append(node.val)
            node = node.prev
        return out
